package app

import (
	"bytes"
	"embed"
	"errors"
	"log"
	"os"
	"path/filepath"
	"strings"
	"time"

	"postbetasoftware.com/whatsdown/internal/media"
	"postbetasoftware.com/whatsdown/internal/store"
)

// demoDataVersion is bumped whenever the seeded demo content changes, so existing
// demo databases are recreated with the new showcase instead of keeping old data.
const demoDataVersion = "release-3"

// Generated by demo_assets/generate.py.
//
//go:embed demo_assets/summit.jpg demo_assets/trail.mp4 demo_assets/voice.ogg demo_assets/release-3-notes.pdf
var demoAssets embed.FS

// resetOutdatedDemoDatabase removes a demo database seeded by an older version.
// Demo data is disposable sample content and never contains real messages.
func resetOutdatedDemoDatabase(dbPath string) {
	marker := dbPath + ".version"
	if current, err := os.ReadFile(marker); err == nil && strings.TrimSpace(string(current)) == demoDataVersion {
		return
	}
	for _, suffix := range []string{"", "-wal", "-shm"} {
		if err := os.Remove(dbPath + suffix); err != nil && !errors.Is(err, os.ErrNotExist) {
			log.Printf("removing outdated demo database: %v", err)
			return
		}
	}
	if err := os.WriteFile(marker, []byte(demoDataVersion+"\n"), 0o600); err != nil {
		log.Printf("writing demo data version: %v", err)
	}
}

// installDemoMedia places the embedded demo files where the media viewers,
// previews and voice player look for downloaded media.
func installDemoMedia() {
	for _, asset := range store.DemoMediaAssets(time.Now()) {
		data, err := demoAssets.ReadFile(filepath.ToSlash(filepath.Join("demo_assets", asset.Asset)))
		if err != nil {
			log.Printf("reading demo asset %s: %v", asset.Asset, err)
			continue
		}
		target := media.GetLocalMediaPath(asset.Message)
		if existing, err := os.ReadFile(target); err == nil && bytes.Equal(existing, data) {
			continue
		}
		if err := os.WriteFile(target, data, 0o600); err != nil {
			log.Printf("installing demo asset %s: %v", asset.Asset, err)
		}
	}
}
